class CarrierQuoteHttpTest {
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();
 private ECKey workload,actorKey;private String issuer,base;private final UUID party=UUID.randomUUID();
 private String token(String client,String scope)throws Exception{Instant now=Instant.now();var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID(workload.getKeyID()).type(JOSEObjectType.JWT).build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-carrier-workload").audience("nigson-integration").claim("azp",client).claim("client_id",client).claim("typ","Bearer").claim("scope",scope).issueTime(Date.from(now)).expirationTime(Date.from(now.plusSeconds(120))).build());jwt.sign(new ECDSASigner(workload));return jwt.serialize();}
 private String actor(String body,UUID correlation)throws Exception{var actor=new ActorAssertion.Actor(party,issuer,"synthetic-customer",null,Set.of("CUSTOMER"),Set.of("carrier.quote_WITH_SIGNED_ACTOR"),null);var binding=new ActorAssertion.Binding("integration","carrier.quote_WITH_SIGNED_ACTOR","POST","/internal/v1/carrier/quotes",correlation,ActorAssertion.Binding.bodyHash(body.getBytes(StandardCharsets.UTF_8)));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID(actorKey.getKeyID()).type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actor,binding,Instant.now()));jwt.sign(new ECDSASigner(actorKey));return jwt.serialize();}
 private HttpResponse<String> post(String token,String actor,String body,UUID correlation,String query)throws Exception{var r=HttpRequest.newBuilder(URI.create(base+"/internal/v1/carrier/quotes"+query)).timeout(Duration.ofSeconds(6)).header("Authorization","Bearer "+token).header("Content-Type","application/json").header("X-Correlation-ID",correlation.toString());if(actor!=null)r.header("X-Nigson-Actor",actor);return http.send(r.POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 private String staffActor(String path,String body,UUID correlation,String role,Instant mfa)throws Exception{var actor=new ActorAssertion.Actor(party,issuer,"synthetic-operations",null,Set.of(role),Set.of("carrier.reconcile_WITH_SIGNED_STAFF"),mfa);var binding=new ActorAssertion.Binding("integration","carrier.reconcile_WITH_SIGNED_STAFF","POST",path,correlation,ActorAssertion.Binding.bodyHash(body.getBytes(StandardCharsets.UTF_8)));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID(actorKey.getKeyID()).type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actor,binding,Instant.now()));jwt.sign(new ECDSASigner(actorKey));return jwt.serialize();}
 private HttpResponse<String> reconcilePost(String path,String token,String actor,String body,UUID key,UUID correlation)throws Exception{var request=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(6)).header("Authorization","Bearer "+token).header("Content-Type","application/json").header("Idempotency-Key",key.toString()).header("X-Correlation-ID",correlation.toString());if(actor!=null)request.header("X-Nigson-Actor",actor);return http.send(request.POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 @org.junit.jupiter.params.ParameterizedTest
 @org.junit.jupiter.params.provider.ValueSource(booleans={false,true})
 void registeredCarrierQuoteUsesRealPrivateTrustAndConfiguredHttpAdapter(boolean intake)throws Exception{
  String db=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(db!=null,"native isolated integration qualification required");if(!db.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_INTEGRATION_DB_REQUIRED");
  workload=new ECKeyGenerator(Curve.P_256).keyID("synthetic-carrier-workload").keyUse(KeyUse.SIGNATURE).algorithm(JWSAlgorithm.ES256).generate();actorKey=new ECKeyGenerator(Curve.P_256).keyID("synthetic-carrier-actor").generate();var provider=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);issuer="http://127.0.0.1:"+provider.getAddress().getPort()+"/realms/synthetic-carrier";var calls=new java.util.concurrent.atomic.AtomicInteger();
  provider.createContext("/realms/synthetic-carrier/protocol/openid-connect/certs",x->{byte[] bytes=new JWKSet(workload.toPublicJWK()).toString().getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,bytes.length);try(var out=x.getResponseBody()){out.write(bytes);}});
  provider.createContext("/oauth/token",x->{x.getRequestBody().readAllBytes();byte[] bytes="{\"access_token\":\"mock-carrier-token\",\"token_type\":\"bearer\",\"expires_in\":3600}".getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,bytes.length);try(var out=x.getResponseBody()){out.write(bytes);}});
  provider.createContext("/rate/v1/rates/quotes",x->{x.getRequestBody().readAllBytes();calls.incrementAndGet();byte[] bytes="{\"output\":{\"rateReplyDetails\":[{\"serviceType\":\"SYNTHETIC_SERVICE\",\"ratedShipmentDetails\":[{\"rateType\":\"ACCOUNT\",\"totalNetCharge\":1234.56,\"shipmentRateDetail\":{\"currency\":\"NGN\"}}]}]}}".getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,bytes.length);try(var out=x.getResponseBody()){out.write(bytes);}});provider.start();
  try(var app=new SpringApplicationBuilder(IntegrationApplication.class).properties(cancellationProperties(intake)).run("--server.port=0","--server.address=127.0.0.1","--APP_ENV=test","--NIGSON_SECURITY_ENABLED=true","--NIGSON_EVENTS_ENABLED=false","--NIGSON_CARRIER_ENABLED=true","--NIGSON_CARRIER_BOOKING_INTAKE_ENABLED="+intake,"--NIGSON_CARRIER_RECONCILIATION_ENABLED="+intake,"--NIGSON_CARRIER_CREATION_GENERATION="+UUID.randomUUID(),"--FEDEX_MODE=MOCK","--FEDEX_BASE_URL=http://127.0.0.1:"+provider.getAddress().getPort(),"--FEDEX_CLIENT_ID=mock-fedex-client","--FEDEX_CLIENT_SECRET=mock-fedex-secret","--FEDEX_ACCOUNT_NUMBER=mock-fedex-account","--NIGSON_CARRIER_SERVICES=SYNTHETIC_SERVICE","--NIGSON_CARRIER_DEFAULT_SERVICE=SYNTHETIC_SERVICE","--NIGSON_CARRIER_PICKUP_TYPE=DROPOFF_AT_FEDEX_LOCATION","--NIGSON_CARRIER_APPROVAL=synthetic-offline-approval","--NIGSON_CARRIER_APPROVAL_UNTIL="+Instant.now().plusSeconds(600),"--NIGSON_OIDC_ISSUER="+issuer,"--NIGSON_PRIVATE_PEER_CIDRS=127.0.0.1/32","--NIGSON_ACTOR_PUBLIC_KEYS="+EventCodec.JSON.writeValueAsString(Map.of(actorKey.getKeyID(),Base64.getEncoder().encodeToString(actorKey.toECPublicKey().getEncoded()))),"--spring.datasource.url="+db+"?currentSchema=integration","--spring.datasource.username=nigson_integration_app","--spring.datasource.password=mock-integration-runtime")){
   assertThat(app.getBeansOfType(CarrierBookingRequestedHandler.class)).hasSize(intake?1:0);
   if(intake){
    base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();UUID cancellation=UUID.randomUUID();String cancelBody=EventCodec.JSON.writeValueAsString(new CarrierCancellationValues.Command(cancellation,UUID.randomUUID(),UUID.randomUUID(),"123456789012","MOCK",Instant.now()));String cancelPath="/internal/v1/carrier/cancellations";UUID cancelCorrelation=UUID.randomUUID();String cancelToken=token("nigson-commerce","carrier.cancel");assertThat(reconcilePost(cancelPath,token("nigson-commerce","jobs.read"),null,cancelBody,cancellation,cancelCorrelation).statusCode()).isEqualTo(401);assertThat(reconcilePost(cancelPath,cancelToken,"invalid",cancelBody,cancellation,cancelCorrelation).statusCode()).isEqualTo(401);assertThat(reconcilePost(cancelPath,cancelToken,null,"{}",cancellation,cancelCorrelation).statusCode()).isEqualTo(400);var missing=reconcilePost(cancelPath,cancelToken,null,cancelBody,cancellation,cancelCorrelation);assertThat(missing.statusCode()).as("validated private cancellation: %s",missing.body()).isEqualTo(503);assertThat(missing.body()).contains("PROVIDER_OUTCOME_UNKNOWN");assertThat(app.getBeansOfType(CarrierCancellationWorker.class)).hasSize(1);
    var event=(tools.jackson.databind.node.ObjectNode)EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(System.getenv("NIGSON_EVENT_FIXTURES"),"shipment.booking.requested.v1.json")));UUID shipment=UUID.randomUUID(),reference=UUID.randomUUID();event.put("event_id",UUID.randomUUID().toString()).put("aggregate_id",shipment.toString());((tools.jackson.databind.node.ObjectNode)event.get("payload")).put("shipment_id",shipment.toString()).put("booking_request_id",reference.toString());var handler=app.getBean(CarrierBookingRequestedHandler.class);assertThat(app.getBean(com.nigson.integration.platform.PlatformStore.class).consume("synthetic-wired-carrier",EventCodec.JSON.writeValueAsString(event),1,handler::handle)).isTrue();assertThat(app.getBean(JdbcTemplate.class).queryForObject("SELECT count(*) FROM integration.integration_job WHERE business_key=? AND kind='LOGISTICS_CREATE' AND state='PENDING'",Integer.class,"carrier-booking:"+reference)).isEqualTo(1);
    base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();String path="/internal/v1/carrier/shipments/"+shipment+"/reconciliation";String commandBody=EventCodec.JSON.writeValueAsString(Map.of("bookingRequestId",reference,"mode","MOCK","reason","Synthetic staff carrier reconciliation"));UUID corr=UUID.randomUUID(),key=UUID.randomUUID();String signedStaff=staffActor(path,commandBody,corr,"OPERATIONS",Instant.now()),workloadToken=token("nigson-commerce","carrier.reconcile_WITH_SIGNED_STAFF");
    assertThat(reconcilePost(path,workloadToken,null,commandBody,key,corr).statusCode()).isIn(401,403);assertThat(reconcilePost(path,token("nigson-commerce","jobs.read"),signedStaff,commandBody,key,corr).statusCode()).isIn(401,403);assertThat(reconcilePost(path,workloadToken,staffActor(path,commandBody,corr,"CUSTOMER",Instant.now()),commandBody,key,corr).statusCode()).isIn(401,403);assertThat(reconcilePost(path,workloadToken,staffActor(path,commandBody,corr,"OPERATIONS",Instant.now().minusSeconds(901)),commandBody,key,corr).statusCode()).isIn(401,403);assertThat(reconcilePost(path,workloadToken,signedStaff,commandBody+" ",key,corr).statusCode()).isIn(401,403);
    var queued=reconcilePost(path,workloadToken,signedStaff,commandBody,key,corr);assertThat(queued.statusCode()).as("private reconciliation: %s",queued.body()).isEqualTo(202);var accepted=EventCodec.JSON.readTree(queued.body());assertThat(accepted.propertyNames()).containsExactlyInAnyOrder("shipmentId","state","jobId");assertThat(accepted.path("jobId").asString()).isEqualTo(app.getBean(JdbcTemplate.class).queryForObject("SELECT id::text FROM integration.integration_job WHERE business_key=?",String.class,"carrier-booking:"+reference));assertThat(accepted.path("state").asString()).isEqualTo("UNKNOWN");assertThat(reconcilePost(path,workloadToken,signedStaff,commandBody,key,corr).body()).isEqualTo(queued.body());assertThat(app.getBean(JdbcTemplate.class).queryForObject("SELECT attempt_count FROM integration.integration_job WHERE business_key=?",Integer.class,"carrier-booking:"+reference)).isZero();assertThat(calls.get()).isZero();

   }
   base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();var address=new CarrierValues.Address("Synthetic Recipient","+2348000000001","Synthetic street",null,"Lagos","LA",null,"NG");UUID cart=UUID.randomUUID();String body=EventCodec.JSON.writeValueAsString(new CarrierValues.QuoteInput(UUID.randomUUID(),cart,"NG","NGN",address,address,List.of(new CarrierValues.Parcel(UUID.randomUUID(),"1","1","10","10","10")),null));
   // Optional fields are omitted on the wire; explicit null serviceCode is invalid.
   var tree=(tools.jackson.databind.node.ObjectNode)EventCodec.JSON.readTree(body);tree.remove("serviceCode");body=EventCodec.JSON.writeValueAsString(tree);UUID correlation=UUID.randomUUID();String signed=actor(body,correlation),valid=token("nigson-commerce","carrier.quote_WITH_SIGNED_ACTOR");
   assertThat(post(valid,null,body,correlation,"").statusCode()).isEqualTo(401);assertThat(post(token("nigson-experience","carrier.quote_WITH_SIGNED_ACTOR"),signed,body,correlation,"").statusCode()).isEqualTo(401);assertThat(post(token("nigson-commerce","jobs.read"),signed,body,correlation,"").statusCode()).isEqualTo(401);assertThat(post(valid,signed,body+" ",correlation,"").statusCode()).isEqualTo(401);assertThat(calls.get()).isZero();
   assertThat(post(valid,signed,body,correlation,"?accountNumber=attacker").statusCode()).isEqualTo(400);var response=post(valid,signed,body,correlation,"");assertThat(response.statusCode()).isEqualTo(200);assertThat(response.headers().firstValue("X-Nigson-Carrier-Mode")).contains("MOCK");assertThat(response.headers().firstValue("X-Nigson-Carrier-Account-SHA256")).contains(app.getBean(com.nigson.integration.providers.CarrierProvider.class).accountFingerprint());assertThat(response.headers().firstValue("Cache-Control")).contains("no-store");var value=EventCodec.JSON.readTree(response.body());assertThat(value.propertyNames()).containsExactlyInAnyOrder("provider","serviceCode","currency","amount","expiresAt","providerReference");assertThat(value.path("amount").asString()).isEqualTo("1234.56");assertThat(post(valid,signed,body,correlation,"").body()).isEqualTo(response.body());assertThat(app.getBean(JdbcTemplate.class).queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,cart)).isEqualTo(1);
  }finally{provider.stop(0);}
 }
 private Map<String,Object> cancellationProperties(boolean enabled)throws Exception{if(!enabled)return Map.of();var storage=EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(System.getenv("NIGSON_TEST_CARRIER_STORAGE_FIXTURE"))));var settings=new HashMap<String,Object>();settings.put("NIGSON_CARRIER_CANCELLATION_ENABLED","true");settings.put("NIGSON_CARRIER_WORKER_ENABLED","true");settings.put("NIGSON_CARRIER_LABELS_ENABLED","true");settings.put("NIGSON_CARRIER_WORKER_DELAY_MS","300000");settings.put("NIGSON_CARRIER_CANCELLATION_DELAY_MS","300000");settings.put("NIGSON_CARRIER_CREATION_NOT_BEFORE",Instant.now().minusSeconds(60).toString());settings.put("NIGSON_CARRIER_LABEL_STOCK","PAPER_4X6");settings.put("NIGSON_CARRIER_BILLING_TYPE","SENDER");settings.put("NIGSON_INTEGRATION_WORKLOAD_SECRET","synthetic-integration-workload-secret-at-least-32-bytes");settings.put("NIGSON_COMMERCE_BASE_URL","http://127.0.0.1:1");settings.put("NIGSON_S3_LOCAL_ENDPOINT",storage.path("endpoint").asString());settings.put("NIGSON_S3_LOCAL_CA",storage.path("ca").asString());settings.put("NIGSON_AWS_REGION",storage.path("region").asString());settings.put("NIGSON_S3_PRIVATE_BUCKET",storage.path("buckets").path(2).asString());return settings;}

}
